import io
import json
import unittest
import zipfile
from solution import restore


def zipped(name='data.json'):
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w') as archive:
        archive.writestr(name, json.dumps({'items': [1, 2]}))
    return output.getvalue()


class TestRestore(unittest.TestCase):
    def test_legacy_json(self):
        self.assertEqual(restore(b'{"items":[1]}'), {'items': [1]})

    def test_current_zip(self):
        self.assertEqual(restore(zipped()), {'items': [1, 2]})

    def test_missing_entry(self):
        with self.assertRaises(ValueError): restore(zipped('other.json'))


if __name__ == '__main__':
    unittest.main()
